node --input-type=module <<'NODE'
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import cp from 'node:child_process';
process.loadEnvFile('apps/cloudflare-worker/.env.local');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'cup-commit-audit-'));
cp.execFileSync('tar',['-xJf','docs/research/speechify-tts-comparison.tar.xz','-C',dir]);
const base=path.join(dir,'speechify-tts-comparison');
let files=0;
for(const name of fs.readdirSync(base)){
const data=fs.readFileSync(path.join(base,name));
for(const key of ['SPEECHIFY_API_KEY','CLOUDFLARE_API_KEY'])if(process.env[key]&&data.includes(Buffer.from(process.env[key])))throw new Error(`Credential in ${name}`);
if(name.startsWith('.env'))throw new Error('Environment file in archive');
if(name.endsWith('.mjs'))cp.execFileSync(process.execPath,['--check',path.join(base,name)]);
files++;
}
console.log(`Archive verified: ${files} files; scripts parse; no configured API keys or env files included.`);
